62	// handleExportSVG serves GET /draw/{id}/export.svg. Background defaults to
63	// transparent; pass ?bg=light or ?bg=dark for an opaque backdrop.
64	func (d *Draw) handleExportSVG(w http.ResponseWriter, r *http.Request, id string) {
65		drawing, err := d.store.Get(id)
66		if err == store.ErrNotFound {
67			http.NotFound(w, r)
68			return
69		}
70		if err != nil {
71			http.Error(w, "storage error", http.StatusInternalServerError)
72			return
73		}
74	
75		var scene svgScene
76		if len(drawing.Scene) > 0 {
77			if err := json.Unmarshal(drawing.Scene, &scene); err != nil {
78				http.Error(w, "invalid scene data", http.StatusInternalServerError)
79				return
80			}
81		}
82	
83		bg := r.URL.Query().Get("bg")
84		svg := renderSceneSVG(scene, bg)
85	
86		w.Header().Set("Content-Type", "image/svg+xml; charset=utf-8")
87		w.Header().Set("Cache-Control", "public, max-age=60, must-revalidate")
88		w.Header().Set("Access-Control-Allow-Origin", "*")
89		// ETag = drawing UpdatedAt so consumers can conditional-GET if they cache.
90		w.Header().Set("ETag", fmt.Sprintf(`"draw-%s-%d"`, id, drawing.UpdatedAt.Unix()))
91		w.Write([]byte(svg))
92	}
