383	// writeShapeText renders multiline text inside a shape (rect, diamond,
384	// ellipse). Each line is a separate <text> element, vertically centred
385	// within the bounding box and clipped to its boundaries.
386	func writeShapeText(b *strings.Builder, text string, bx, by, bw, bh, fs float64, ff, stroke string, op float64, rot string) {
387		lines := strings.Split(text, "\n")
388		lh := fs * 1.3
389		totalH := float64(len(lines)) * lh
390		// Vertical start so the block is centred in the box.
391		startY := by + bh/2 - totalH/2 + fs*0.85
392		anchor := "middle"
393		cx := bx + bw/2
394		for i, line := range lines {
395			ly := startY + float64(i)*lh
396			fmt.Fprintf(b, `  <text x="%s" y="%s" text-anchor="%s" font-size="%s" font-family="%s" fill="%s" opacity="%s"%s>%s</text>`,
397				f(cx), f(ly), anchor, f(fs), ff, escAttr(stroke), f(op), rot, escText(line))
398			b.WriteByte('\n')
399		}
400	}
